  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var TZ = 'Africa/Cairo';
  var REFRESH_LIVE_MS = 30 * 1000;                         // today with a live match
  var REFRESH_IDLE_MS = 2 * 60 * 1000;                     // today, nothing live
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;
  // League order: these first (same ids as the standings / predictions pages), then the rest.
  var PRIORITY = ['937599', '943230', '938652', '943009', '941825', '936357', '938769', '937873',
    '20580897', '943487', '943229', '943231', '34872360', '942806', '97887515', '938823', '939779',
    '939531', '941155', '943983', '54771544', '41791876'];

