  function matchesUrl(iso) { return WORKER_BASE_URL + '/api/matches/matches_date_get/' + iso + '/' + encodeURI(MATCH_FILTERS) + '/D/60'; }
  function matchInfoUrl(id) { return WORKER_BASE_URL + '/api/matches/match_info/' + encodeURIComponent(id) + '/D/60'; }
