      : `<span class="match-time">${esc(m.time)}</span>`;
    return `<a class="match-card match-card--${m.status === 'other' ? 'upcoming' : m.status}" href="${esc(matchPageUrl(m.id))}">
        <div class="match-card__top"><span class="match-card__league">${esc(m.league)}</span><span class="match-card__round">${esc(m.round)}</span></div>
        <div class="match-card__body">
          ${teamHtml(m.home)}
          <div class="match-center">${center}<span class="badge badge--${m.status === 'live' ? 'live' : m.status === 'finished' ? 'finished' : 'upcoming'}">${badgeHtml(m)}</span></div>
          ${teamHtml(m.away)}
        </div>
        <div class="match-card__bottom">${coverageHtml(m)}</div>
      </a>`;
  }

  // ------------------------------------------------------------------ state
  var today = dayKey(Date.now());
  var hashDate = /date=(\d{4}-\d{2}-\d{2})/.exec(location.hash);
  var state = {
