      b.classList.toggle('is-active', on);
      b.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    var custom = [offsets['-1'], offsets['0'], offsets['1']].indexOf(state.date) === -1;
    var picker = dayBar.querySelector('.mc-picker');
    if (picker) picker.classList.toggle('is-active', custom);
    if (dateInput && dateInput.value !== state.date) dateInput.value = state.date;
    if (dateLabel) {
      try {
        dateLabel.textContent = new Intl.DateTimeFormat(window.pxlLocale(), { timeZone: 'UTC', weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })
          .format(new Date(state.date + 'T12:00:00Z'));
      } catch (e) { dateLabel.textContent = state.date; }
    }
  }
  function renderFilters() {
