    var leagues = {}, order = [];
    state.matches.forEach(function (m) {
      if (!leagues[m.leagueId]) { leagues[m.leagueId] = { id: m.leagueId, name: m.league, n: 0 }; order.push(leagues[m.leagueId]); }
      if (statusMatches(m, state.status) && textMatches(m)) leagues[m.leagueId].n++;
    });
    if (state.league !== 'all' && !leagues[state.league]) state.league = 'all';
    order.sort(function (a, b) { return leagueRank(a.id) - leagueRank(b.id) || b.n - a.n; });
    var chip = function (id, name, n, on) {
      return `<button type="button" role="tab" class="league-chip${on ? ' is-active' : ''}" aria-selected="${on}" data-league="${esc(id)}"${n === 0 && !on ? ' data-empty' : ''}>${esc(name)}<span class="mc-chip-n">${n}</span></button>`;
    };
    var total = state.matches.filter(function (m) { return statusMatches(m, state.status) && textMatches(m); }).length;
    leagueBar.innerHTML = chip('all', 'كل البطولات', total, state.league === 'all') +
