  }
  function renderAll() { renderDays(); renderFilters(); renderList(); }

  // ------------------------------------------------------------------ loading
  async function loadLiveInfo(matches) {
    var live = matches.filter(function (m) { return m.status === 'live'; }).slice(0, 12);
    await Promise.all(live.map(async function (m) {
      try {
        var d = ((await fetchJson(matchInfoUrl(m.id), 1)) || {}).data || {};
        var cc = Array.isArray(d.channel_commm) && d.channel_commm.length ? d.channel_commm[0] : {};
        liveInfo[m.id] = { at: Date.now(), phase: window.pxlLive.phase(d, true), clock: window.pxlLive.clock(d), round: d.round || '', channel: cc.channel_name || '', commentator: cc.commentator_name || '' };
      } catch (e) { /* card keeps the list phase, no minute */ }
    }));
    matches.forEach(function (m) {
      var i = liveInfo[m.id];
      if (!i || m.status !== 'live') return;
      // Phase + clock only from a FRESH match_info (a failed refresh never leaves a 1st-half
      // minute on a match that is now at half-time); otherwise the list row phase, no minute.
      if (Date.now() - i.at < LIVE_INFO_MAX_AGE_MS) { m.phase = i.phase || m.phase; m.clock = i.clock; }
      if (i.round && !m.round) m.round = i.round;
      if (i.channel && !m.channel) m.channel = i.channel;
      if (i.commentator && !m.commentator) m.commentator = i.commentator;
    });
    return matches;
  }
  async function load(silent) {
    var mySeq = ++seq, date = state.date;
    clearTimeout(refreshTimer);
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      state.loading = false; state.error = 'لم يتم ضبط رابط خادم المباريات.'; renderAll(); return;
    }
    var cached = cache[date];
    var fresh = cached && (date !== today ? true : Date.now() - cached.at < 25000);
    if (fresh && !silent) {
      state.matches = cached.matches; state.loading = false; state.error = ''; renderAll(); schedule(); return;
    }
    if (!silent) { state.loading = true; state.error = ''; renderAll(); }
    try {
      var json = await fetchJson(matchesUrl(date), silent ? 1 : 3);
      var matches = (Array.isArray(json && json.data) ? json.data : []).map(parseMatch);
      if (date === today) matches = await loadLiveInfo(matches);
      if (mySeq !== seq) return;                            // the user picked another day meanwhile
      cache[date] = { at: Date.now(), matches: matches };
      state.matches = matches; state.loading = false; state.error = '';
      renderAll();
    } catch (err) {
      if (mySeq !== seq) return;
      console.warn('[PX League] matches page:', err);
      if (!silent || !state.matches.length) { state.loading = false; state.error = 'تعذّر تحميل المباريات حاليًا.'; renderAll(); }
    }
    schedule();
  }
  // Silent refresh only for today; paused while the tab is hidden.
  function schedule() {
    clearTimeout(refreshTimer);
    if (state.date !== today || document.hidden) return;
    var anyLive = state.matches.some(function (m) { return m.status === 'live'; });
    refreshTimer = setTimeout(function () { load(true); }, anyLive ? REFRESH_LIVE_MS : REFRESH_IDLE_MS);
  }
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) clearTimeout(refreshTimer);
    else if (state.date === today) load(true);
  });

  function setDate(date) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || date === state.date) return;
    state.date = date;
    state.league = 'all';
    try { history.replaceState(null, '', location.pathname + location.search + (date === today ? '' : '#date=' + date)); } catch (e) {}
    load(false);
  }

  // ------------------------------------------------------------------ events
  dayBar.addEventListener('click', function (e) {
    var b = e.target.closest('[data-offset]');
    if (b) setDate(shiftDay(today, Number(b.getAttribute('data-offset'))));
  });
  if (dateInput) dateInput.addEventListener('change', function () { setDate(dateInput.value); });
  statusBar.addEventListener('click', function (e) {
    var b = e.target.closest('[data-status]');
    if (!b || b.classList.contains('is-active')) return;
    state.status = b.getAttribute('data-status');
    renderFilters(); renderList();
  });
  leagueBar.addEventListener('click', function (e) {
    var b = e.target.closest('[data-league]');
    if (!b || b.classList.contains('is-active')) return;
    state.league = b.getAttribute('data-league');
    renderFilters(); renderList();
  });
  var searchTimer = null;
  if (searchEl) searchEl.addEventListener('input', function () {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(function () { state.query = norm(searchEl.value); renderFilters(); renderList(); }, 150);
  });
  listEl.addEventListener('click', function (e) {
    if (e.target.closest('[data-retry]')) { load(false); return; }
    if (e.target.closest('[data-reset]')) {
      state.status = 'all'; state.league = 'all'; state.query = '';
      if (searchEl) searchEl.value = '';
      renderFilters(); renderList();
    }
  });

  load(false);
})();
//

//
(function () {
  'use strict';
  if (location.pathname !== '/p/predictions.html') return;   // client-side route guard

  // ------------------------------------------------------------------ config
  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';
  var MATCH_FILTERS = window.PXL_MATCH_FILTERS;       // shared: SETTINGS script at the top
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var TZ = 'Africa/Cairo';
  var DAYS_AHEAD = 4;                                  // today + 3 days of fixtures
  var POINTS_EXACT = 10, POINTS_WINNER = 5;
  var MAX_GOALS = 20;
  // Championships open for predictions (ysscores season ids, same as the standings page).
  // Override with window.PXL_PREDICTION_LEAGUES = ['937599', ...] before this script.
  var LEAGUES = (window.PXL_PREDICTION_LEAGUES || [
    '937599', '943230', '938652', '943009', '941825', '936357', '938769', '937873', '20580897',
    '943487', '943229', '943231', '34872360', '942806', '97887515', '938823', '939779', '939531',
    '941155', '943983', '54771544', '41791876'
  ]).map(String);
  var COUNTRIES = [
    ['eg', 'مصر', '🇪🇬'], ['sa', 'السعودية', '🇸🇦'], ['ae', 'الإمارات', '🇦🇪'], ['qa', 'قطر', '🇶🇦'],
    ['kw', 'الكويت', '🇰🇼'], ['bh', 'البحرين', '🇧🇭'], ['om', 'عُمان', '🇴🇲'], ['jo', 'الأردن', '🇯🇴'],
    ['ps', 'فلسطين', '🇵🇸'], ['lb', 'لبنان', '🇱🇧'], ['sy', 'سوريا', '🇸🇾'], ['iq', 'العراق', '🇮🇶'],
    ['ye', 'اليمن', '🇾🇪'], ['ma', 'المغرب', '🇲🇦'], ['dz', 'الجزائر', '🇩🇿'], ['tn', 'تونس', '🇹🇳'],
    ['ly', 'ليبيا', '🇱🇾'], ['sd', 'السودان', '🇸🇩'], ['mr', 'موريتانيا', '🇲🇷'], ['so', 'الصومال', '🇸🇴'],
    ['tr', 'تركيا', '🇹🇷'], ['gb', 'بريطانيا', '🇬🇧'], ['fr', 'فرنسا', '🇫🇷'], ['de', 'ألمانيا', '🇩🇪'],
    ['us', 'أمريكا', '🇺🇸'], ['xx', 'دولة أخرى', '🌍']
  ];
  var NS = 'pxl.pred.v1.';                             // localStorage namespace (versioned)

  var root = document.getElementById('predictions-page');
  var grid = document.getElementById('pred-grid');
  var dayBar = document.getElementById('pred-days');
  var leagueBar = document.getElementById('pred-leagues');
  var authBox = document.getElementById('pred-auth');
  var boardList = document.getElementById('pred-board');
  var countEl = document.getElementById('pred-count');
  if (!root || !grid || !dayBar || !leagueBar || !authBox || !boardList) return;

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function imgUrl(base, value) {
    var v = String(value || '').trim();
    if (/^https:\/\//i.test(v)) return v;
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(v) ? base + encodeURIComponent(v) : '';
  }
  function load(key, fallback) {
    try { var v = JSON.parse(localStorage.getItem(NS + key)); return v == null ? fallback : v; } catch (e) { return fallback; }
  }
  function store(key, value) {
    try { localStorage.setItem(NS + key, JSON.stringify(value)); return true; } catch (e) { return false; }
  }
  function country(code) { for (var i = 0; i < COUNTRIES.length; i++) if (COUNTRIES[i][0] === code) return COUNTRIES[i]; return null; }
  function clampGoals(n) { n = Math.round(Number(n)); return isFinite(n) ? Math.max(0, Math.min(MAX_GOALS, n)) : 0; }
  function toHex(bytes) { return Array.prototype.map.call(bytes, function (b) { return ('0' + b.toString(16)).slice(-2); }).join(''); }
  // Score text in RTL order: home goals on the right, like the card (RLM marks fix the bidi order).
  function scoreText(h, a) { return h + '‏-‏' + a; }
  function initial(name) { return (String(name || '?').trim().charAt(0) || '?').toUpperCase(); }

  var dayKeyFmt = new Intl.DateTimeFormat('en-CA', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' });
  var timeFmt = new Intl.DateTimeFormat(window.pxlLocale(true), { timeZone: TZ, hour: 'numeric', minute: '2-digit' });
  var dateFmt = new Intl.DateTimeFormat(window.pxlLocale(true), { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long' });
  var shortDayFmt = new Intl.DateTimeFormat(window.pxlLocale(true), { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'numeric' });
  function dayKey(ms) { return dayKeyFmt.format(new Date(ms)); }                 // YYYY-MM-DD, Cairo
  function dayLabel(key) {
    if (key === dayKey(Date.now())) return 'اليوم';
    if (key === dayKey(Date.now() + 864e5)) return 'غدًا';
    return shortDayFmt.format(new Date(key + 'T12:00:00Z'));
  }
  function kickoffText(ts) { return dateFmt.format(new Date(ts)) + ' · ' + timeFmt.format(new Date(ts)); }

  // ------------------------------------------------------------------ matches + scoring
  function parseMatch(r, feedDate) {
    var c = r.championship || {}, h = r.home_team || {}, a = r.away_team || {};
    var ts = Number(r.match_timestamp) * 1000 || 0;
    return {
      id: String(r.match_id || ''), ts: ts, day: ts ? dayKey(ts) : '', feedDate: feedDate,
      status: Number(r.status) || 0,
      leagueId: String(r.championship_id || c.url_id || ''), league: c.title || '',
      leagueLogo: imgUrl(LEAGUE_LOGO_BASE, c.image),
      home: h.title || '', away: a.title || '',
      homeLogo: imgUrl(TEAM_LOGO_BASE, h.image), awayLogo: imgUrl(TEAM_LOGO_BASE, a.image),
      hs: r.home_scores, as: r.away_scores
    };
  }
  function snapshot(m) {          // what a saved prediction keeps about its match
    return { id: m.id, ts: m.ts, day: m.day, feedDate: m.feedDate, leagueId: m.leagueId, league: m.league,
      home: m.home, away: m.away, homeLogo: m.homeLogo, awayLogo: m.awayLogo };
  }
  function isLocked(m) { return m.status !== 0 || Date.now() >= m.ts; }
  function startedAt(ts) { return Date.now() >= ts; }

  var results = load('results', {});                   // matchId -> [home, away] (final scores never change)
  function recordResults(list) {
    var changed = false;
    list.forEach(function (m) {
      if (m.status === 4 && m.hs != null && m.as != null && !results[m.id]) {
        results[m.id] = [Number(m.hs), Number(m.as)];
        changed = true;
      }
    });
    if (changed) store('results', results);
    return changed;
  }
  function outcome(h, a) { return h > a ? 1 : (h < a ? -1 : 0); }
  function pointsFor(p) {
    var r = p && p.match && results[p.match.id];
    if (!r) return null;
    if (p.h === r[0] && p.a === r[1]) return POINTS_EXACT;
    return outcome(p.h, p.a) === outcome(r[0], r[1]) ? POINTS_WINNER : 0;
  }
  function statsFor(preds) {
    var s = { points: 0, exact: 0, winner: 0, total: preds.length, settled: 0 };
    preds.forEach(function (p) {
      var pts = pointsFor(p);
      if (pts == null) return;
      s.settled++;
      s.points += pts;
      if (pts === POINTS_EXACT) s.exact++;
      else if (pts === POINTS_WINNER) s.winner++;
    });
    return s;
  }

  // ------------------------------------------------------------------ data layer
  /* Backend hook: define window.PXL_PREDICTIONS_API (before this script) with the same
     async methods as localStore below, backed by Supabase / the Worker:
       me() -> user | null                     user = { handle, name, country }
       register({ handle, name, country, password }) -> user (and signs in)
       login({ handle, password }) -> user      logout()
       savePrediction(handle, match, home, away) -> { h, a, savedAt, match }
       predictions(handle) -> [{ h, a, savedAt, match }]
       listUsers() -> [user]
       leaderboard() (optional) -> [{ rank, user, points, exact, winner, total }]
     The server must enforce the kickoff lock and compute points itself. */
  function publicUser(u) { return { handle: u.handle, name: u.name, country: u.country }; }
  async function hashPassword(password, salt) {
    if (!(window.crypto && crypto.subtle && window.TextEncoder)) throw new Error('المتصفح لا يدعم تسجيل الدخول الآمن.');
    var enc = new TextEncoder();
    var key = await crypto.subtle.importKey('raw', enc.encode(password), 'PBKDF2', false, ['deriveBits']);
    var bits = await crypto.subtle.deriveBits({ name: 'PBKDF2', salt: enc.encode(salt), iterations: 100000, hash: 'SHA-256' }, key, 256);
    return toHex(new Uint8Array(bits));
  }
  function normHandle(v) { v = String(v || '').trim().toLowerCase().replace(/^@/, ''); return /^[a-z0-9_]{3,20}$/.test(v) ? v : ''; }

  var localStore = {
    users: function () { return load('users', {}); },
    me: async function () { var u = localStore.users()[load('session', '')]; return u ? publicUser(u) : null; },
    register: async function (o) {
      var handle = normHandle(o.handle);
      if (!handle) throw new Error('اسم المستخدم من 3 إلى 20 حرفًا: حروف إنجليزية أو أرقام أو _');
      if (String(o.password || '').length < 6) throw new Error('كلمة المرور 6 أحرف على الأقل.');
      var users = localStore.users();
      if (users[handle]) throw new Error('اسم المستخدم مستخدم بالفعل.');
      var salt = toHex(crypto.getRandomValues(new Uint8Array(16)));
      users[handle] = {
        handle: handle, name: String(o.name || '').trim().slice(0, 30) || handle,
        country: country(o.country) ? o.country : 'xx',
        salt: salt, hash: await hashPassword(String(o.password), salt), createdAt: Date.now()
      };
      if (!store('users', users) || !store('session', handle)) throw new Error('تعذّر الحفظ على هذا الجهاز.');
      return publicUser(users[handle]);
    },
    login: async function (o) {
      var handle = normHandle(o.handle);
      var u = localStore.users()[handle];
      if (!u || (await hashPassword(String(o.password || ''), u.salt)) !== u.hash) throw new Error('اسم المستخدم أو كلمة المرور غير صحيحة.');
      store('session', handle);
      return publicUser(u);
    },
    logout: async function () { try { localStorage.removeItem(NS + 'session'); } catch (e) {} },
    savePrediction: async function (handle, match, h, a) {
      if (startedAt(match.ts)) throw new Error('التوقع مغلق: بدأت المباراة.');
      var all = load('predictions', {});
      var mine = all[handle] || (all[handle] = {});
      mine[match.id] = { h: clampGoals(h), a: clampGoals(a), savedAt: Date.now(), match: snapshot(match) };
      if (!store('predictions', all)) throw new Error('تعذّر الحفظ على هذا الجهاز.');
      return mine[match.id];
    },
    predictions: async function (handle) {
      var mine = load('predictions', {})[handle] || {};
      return Object.keys(mine).map(function (k) { return mine[k]; });
    },
    listUsers: async function () {
      var users = localStore.users();
      return Object.keys(users).map(function (k) { return publicUser(users[k]); });
    }
  };
  var api = window.PXL_PREDICTIONS_API || localStore;
  var isLocal = api === localStore;

  async function leaderboard() {
    if (typeof api.leaderboard === 'function') return api.leaderboard();
    var users = await api.listUsers();
    var rows = await Promise.all(users.map(async function (u) {
      var preds = await api.predictions(u.handle);
      return Object.assign({ user: u, preds: preds }, statsFor(preds));
    }));
    rows.sort(function (x, y) {
      return y.points - x.points || y.exact - x.exact || y.winner - x.winner || x.user.handle.localeCompare(y.user.handle);
    });
    rows.forEach(function (r, i) { r.rank = i + 1; });
    return rows;
  }

  // ------------------------------------------------------------------ state
  var state = { matches: [], loading: true, error: '', day: 'all', league: 'all', me: null, mine: {}, drafts: {}, board: [] };
  var lockedAtRender = {};
  var authTab = 'login';

  async function loadMine() {
    state.mine = {};
    if (!state.me) return;
    try {
      (await api.predictions(state.me.handle)).forEach(function (p) { if (p && p.match) state.mine[p.match.id] = p; });
    } catch (e) { console.warn('[PX League] predictions:', e); }
  }
  function matchById(id) { for (var i = 0; i < state.matches.length; i++) if (state.matches[i].id === id) return state.matches[i]; return null; }
  function currentPick(m) {
    var d = state.drafts[m.id], p = state.mine[m.id];
    return d ? d.slice() : (p ? [p.h, p.a] : [0, 0]);
  }

  // ------------------------------------------------------------------ filters
  function chip(kind, value, label, active) {
    return `<button type="button" role="tab" class="league-chip${active ? ' is-active' : ''}" aria-selected="${active}" data-${kind}="${esc(value)}">${esc(label)}</button>`;
  }
  function renderFilters() {
    var days = [], leagues = [], seenDay = {}, seenLeague = {};
    state.matches.forEach(function (m) { if (!seenDay[m.day]) { seenDay[m.day] = 1; days.push(m.day); } });
    days.sort();
    if (state.day !== 'all' && !seenDay[state.day]) state.day = 'all';
    state.matches.forEach(function (m) {
      if ((state.day === 'all' || m.day === state.day) && !seenLeague[m.leagueId]) {
        seenLeague[m.leagueId] = 1;
        leagues.push({ id: m.leagueId, name: m.league });
      }
    });
    leagues.sort(function (x, y) {
      var a = LEAGUES.indexOf(x.id), b = LEAGUES.indexOf(y.id);
      return (a === -1 ? 999 : a) - (b === -1 ? 999 : b);
    });
    if (state.league !== 'all' && !seenLeague[state.league]) state.league = 'all';
    dayBar.innerHTML = chip('day', 'all', 'كل الأيام', state.day === 'all') +
      days.map(function (d) { return chip('day', d, dayLabel(d), state.day === d); }).join('');
    leagueBar.innerHTML = chip('league', 'all', 'كل البطولات', state.league === 'all') +
      leagues.map(function (l) { return chip('league', l.id, l.name, state.league === l.id); }).join('');
    dayBar.hidden = leagueBar.hidden = !state.matches.length;
  }
  function visibleMatches() {
    return state.matches.filter(function (m) {
      return (state.day === 'all' || m.day === state.day) && (state.league === 'all' || m.leagueId === state.league);
    });
  }

  // ------------------------------------------------------------------ match cards
  function teamHtml(name, logo) {
    return `<div class="pred-team">${logo
      ? `<img src="${esc(logo)}" alt="" width="48" height="48" loading="lazy" referrerpolicy="no-referrer" onerror="this.style.visibility='hidden'">`
      : `<span class="pred-team__ph">${esc(initial(name))}</span>`}<span>${esc(name)}</span></div>`;
  }
  function stepperHtml(side, value, teamName, locked) {
    var label = 'أهداف ' + teamName;
    return `<div class="pred-stepper" dir="ltr">
        <button type="button" data-step="-1" data-side="${side}" aria-label="إنقاص ${esc(label)}"${locked || value <= 0 ? ' disabled' : ''}>−</button>
        <input type="number" inputmode="numeric" min="0" max="${MAX_GOALS}" value="${value}" data-side="${side}" aria-label="${esc(label)}"${locked ? ' disabled' : ''}>
        <button type="button" data-step="1" data-side="${side}" aria-label="زيادة ${esc(label)}"${locked || value >= MAX_GOALS ? ' disabled' : ''}>+</button>
      </div>`;
  }
  function statusOf(m, pick, locked) {
    var p = state.mine[m.id];
    if (locked) {
      if (!p) return { kind: 'locked', text: 'التوقع مغلق · 0 نقطة' };
      var pts = pointsFor(p);
      if (pts == null) return { kind: 'locked', text: 'التوقع مغلق · توقعك ' + scoreText(p.h, p.a) + ' · بانتظار النتيجة' };
      var r = results[m.id];
      return { kind: pts === POINTS_EXACT ? 'exact' : (pts === POINTS_WINNER ? 'winner' : 'miss'),
        text: 'التوقع مغلق · ' + pts + ' نقطة (النتيجة ' + scoreText(r[0], r[1]) + ')' };
    }
    if (!state.me) return { kind: 'guest', text: 'سجّل الدخول أولاً' };
    if (p && p.h === pick[0] && p.a === pick[1]) return { kind: 'saved', text: 'تم الحفظ ✓' };
    if (p) return { kind: 'dirty', text: 'عدّلت توقعك، اضغط «تحديث التوقع» للحفظ' };
    return { kind: 'idle', text: 'اختر النتيجة ثم احفظ' };
  }
  function saveLabel(m, locked) { return locked ? 'التوقع مغلق' : (state.mine[m.id] ? 'تحديث التوقع' : 'حفظ التوقع'); }
  function cardHtml(m, i) {
    var locked = isLocked(m), pick = currentPick(m), st = statusOf(m, pick, locked);
    lockedAtRender[m.id] = locked;
    return `<article class="pred-card${locked ? ' is-locked' : ''}${state.mine[m.id] ? ' has-pick' : ''}" data-id="${esc(m.id)}" style="--i:${Math.min(i, 12)}">
      <header class="pred-card__meta">
        <span class="pred-card__league">${m.leagueLogo ? `<img src="${esc(m.leagueLogo)}" alt="" width="18" height="18" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}<span>${esc(m.league)}</span></span>
        <time datetime="${new Date(m.ts).toISOString()}">${esc(kickoffText(m.ts))}</time>
      </header>
      <div class="pred-card__teams">
        ${teamHtml(m.home, m.homeLogo)}
        <span class="pred-vs">ضد</span>
        ${teamHtml(m.away, m.awayLogo)}
      </div>
      <div class="pred-score">
        ${stepperHtml('h', pick[0], m.home, locked)}
        <span class="pred-score__sep">-</span>
        ${stepperHtml('a', pick[1], m.away, locked)}
      </div>
      <button type="button" class="pred-save" data-save${locked ? ' disabled' : ''}>${saveLabel(m, locked)}</button>
      <p class="pred-status pred-status--${st.kind}" role="status">${esc(st.text)}</p>
    </article>`;
  }
  function syncCard(card, m) {
    var locked = isLocked(m), pick = currentPick(m), st = statusOf(m, pick, locked);
    ['h', 'a'].forEach(function (side, idx) {
      var input = card.querySelector('input[data-side="' + side + '"]');
      if (input && document.activeElement !== input) input.value = pick[idx];
      var minus = card.querySelector('[data-step="-1"][data-side="' + side + '"]');
      var plus = card.querySelector('[data-step="1"][data-side="' + side + '"]');
      if (minus) minus.disabled = locked || pick[idx] <= 0;
      if (plus) plus.disabled = locked || pick[idx] >= MAX_GOALS;
    });
    var btn = card.querySelector('[data-save]');
    if (btn && !btn.classList.contains('is-busy')) { btn.textContent = saveLabel(m, locked); btn.disabled = locked; }
    setStatus(card, st.kind, st.text);
    card.classList.toggle('has-pick', !!state.mine[m.id]);
  }
  function setStatus(card, kind, text) {
    var el = card.querySelector('.pred-status');
    if (!el) return;
    el.className = 'pred-status pred-status--' + kind;
    el.textContent = text;
  }
  function skeletonCards() {
    var one = '<div class="pred-sk" aria-hidden="true"><span class="sk" style="width:65%"></span>' +
      '<div class="pred-sk__teams"><span class="sk sk--crest"></span><span class="sk" style="width:36px"></span><span class="sk sk--crest"></span></div>' +
      '<span class="sk sk--btn"></span></div>';
    return '<span class="visually-hidden" role="status">جاري تحميل المباريات...</span>' + one + one + one + one;
  }
  function renderGrid() {
    if (state.loading) { grid.innerHTML = skeletonCards(); if (countEl) countEl.textContent = ''; return; }
    if (state.error && !state.matches.length) {
      grid.innerHTML = `<div class="pred-empty"><span>${esc(state.error)}</span><button type="button" class="standings-retry pred-retry">إعادة المحاولة</button></div>`;
      if (countEl) countEl.textContent = '';
      return;
    }
    var list = visibleMatches();
    if (countEl) countEl.textContent = list.length ? list.length + ' مباراة' : '';
    grid.innerHTML = list.length
      ? list.map(cardHtml).join('')
      : '<div class="pred-empty">لا توجد مباريات متاحة لهذا الاختيار حاليًا.</div>';
  }

  function readCard(card) {
    return ['h', 'a'].map(function (side) {
      var input = card.querySelector('input[data-side="' + side + '"]');
      return clampGoals(input ? input.value : 0);
    });
  }
  grid.addEventListener('click', function (e) {
    if (e.target.closest('.pred-retry')) { loadMatches(); return; }
    var card = e.target.closest('.pred-card');
    var m = card && matchById(card.getAttribute('data-id'));
    if (!m) return;
    var step = e.target.closest('[data-step]');
    if (step && !step.disabled) {
      var pick = currentPick(m), idx = step.getAttribute('data-side') === 'h' ? 0 : 1;
      pick[idx] = clampGoals(pick[idx] + Number(step.getAttribute('data-step')));
      state.drafts[m.id] = pick;
      syncCard(card, m);
      return;
    }
    if (e.target.closest('[data-save]')) savePick(card, m);
  });
  grid.addEventListener('input', function (e) {
    if (!e.target.matches('input[data-side]')) return;
    var card = e.target.closest('.pred-card'), m = card && matchById(card.getAttribute('data-id'));
    if (!m) return;
    state.drafts[m.id] = readCard(card);
    syncCard(card, m);
  });
  grid.addEventListener('change', function (e) {      // normalise typed values (e.g. "", -1, 99)
    if (!e.target.matches('input[data-side]')) return;
    var card = e.target.closest('.pred-card'), m = card && matchById(card.getAttribute('data-id'));
    if (!m) return;
    e.target.value = clampGoals(e.target.value);
    state.drafts[m.id] = readCard(card);
    syncCard(card, m);
  });

  async function savePick(card, m) {
    if (!state.me) {
      setStatus(card, 'guest', 'سجّل الدخول أولاً');
      authBox.scrollIntoView({ behavior: 'smooth', block: 'center' });
      var first = authBox.querySelector('input');
      if (first) setTimeout(function () { first.focus({ preventScroll: true }); }, 350);
      return;
    }
    if (isLocked(m)) { syncCard(card, m); return; }
    var btn = card.querySelector('[data-save]');
    var pick = currentPick(m);
    btn.disabled = true;
    btn.classList.add('is-busy');
    btn.textContent = 'جارٍ الحفظ...';
    try {
      state.mine[m.id] = await api.savePrediction(state.me.handle, m, pick[0], pick[1]);
      delete state.drafts[m.id];
      card.classList.remove('is-flash');
      void card.offsetWidth;                               // restart the flash animation
      card.classList.add('is-flash');
      btn.classList.remove('is-busy');
      syncCard(card, m);
      refreshBoard();
    } catch (err) {
      btn.classList.remove('is-busy');
      syncCard(card, m);
      setStatus(card, 'error', (err && err.message) || 'تعذّر حفظ التوقع.');
    }
  }

  dayBar.addEventListener('click', function (e) {
    var c = e.target.closest('[data-day]');
    if (!c || c.classList.contains('is-active')) return;
    state.day = c.getAttribute('data-day');
    renderFilters();
    renderGrid();
  });
  leagueBar.addEventListener('click', function (e) {
    var c = e.target.closest('[data-league]');
    if (!c || c.classList.contains('is-active')) return;
    state.league = c.getAttribute('data-league');
    renderFilters();
    renderGrid();
  });

  // ------------------------------------------------------------------ auth / profile card
  function countryOptions() {
    return COUNTRIES.map(function (c) { return `<option value="${c[0]}">${c[2]} ${esc(c[1])}</option>`; }).join('');
  }
  function renderAuth() {
    if (state.me) { renderProfile(); return; }
    var reg = authTab === 'register';
    authBox.innerHTML = `
      <div class="pred-tabs" role="tablist" aria-label="الحساب">
        <button type="button" role="tab" class="pred-tab${reg ? '' : ' is-active'}" aria-selected="${!reg}" data-auth-tab="login">دخول</button>
        <button type="button" role="tab" class="pred-tab${reg ? ' is-active' : ''}" aria-selected="${reg}" data-auth-tab="register">حساب جديد</button>
      </div>
      <form class="pred-form" novalidate="">
        <label>اسم المستخدم
          <input name="handle" autocomplete="username" required maxlength="21" dir="ltr" placeholder="px_fan" autocapitalize="none" spellcheck="false">
        </label>
        ${reg ? `<label>الاسم الظاهر <small>(اختياري)</small>
          <input name="name" maxlength="30" autocomplete="nickname" placeholder="مثال: أحمد">
        </label>
        <label>الدولة
          <select name="country">${countryOptions()}</select>
        </label>` : ''}
        <label>كلمة المرور
          <input type="password" name="password" required minlength="6" dir="ltr" autocomplete="${reg ? 'new-password' : 'current-password'}">
        </label>
        <p class="pred-form__error" role="alert"></p>
        <button type="submit" class="pred-submit">${reg ? 'إنشاء الحساب' : 'دخول'}</button>
        ${isLocal ? '<p class="pred-form__note">الحساب والتوقعات محفوظة على هذا الجهاز فقط حاليًا.</p>' : ''}
      </form>`;
  }
  function myRow() {
    if (!state.me) return null;
    for (var i = 0; i < state.board.length; i++) if (state.board[i].user.handle === state.me.handle) return state.board[i];
    return null;
  }
  function renderProfile() {
    var me = state.me, row = myRow() || {}, c = country(me.country);
    authBox.innerHTML = `
      <div class="pred-profile">
        <div class="pred-profile__head">
          <span class="pred-avatar" aria-hidden="true">${esc(initial(me.name))}</span>
          <div>
            <b>${esc(me.name)}</b>
            <small><span dir="ltr">@${esc(me.handle)}</span>${c ? ' · ' + c[2] + ' ' + esc(c[1]) : ''}</small>
          </div>
        </div>
        <div class="pred-stats">
          <div><b>${row.rank ? '#' + row.rank : '—'}</b><span>ترتيبك</span></div>
          <div class="is-brand"><b>${row.points || 0}</b><span>نقطة</span></div>
          <div><b>${row.exact || 0}</b><span>نتيجة صحيحة</span></div>
          <div><b>${row.winner || 0}</b><span>فائز صحيح</span></div>
        </div>
        <div class="pred-profile__foot">
          <span>${Object.keys(state.mine).length} توقع محفوظ</span>
          <button type="button" class="pred-logout" data-logout>تسجيل الخروج</button>
        </div>
      </div>`;
  }
  authBox.addEventListener('click', async function (e) {
    var tab = e.target.closest('[data-auth-tab]');
    if (tab) {
      authTab = tab.getAttribute('data-auth-tab');
      renderAuth();
      var input = authBox.querySelector('input');
      if (input) input.focus();
      return;
    }
    if (e.target.closest('[data-logout]')) {
      await api.logout();
      authTab = 'login';
      state.me = null;
      state.mine = {};
      state.drafts = {};
      renderAuth();
      renderGrid();
      renderBoard();
    }
  });
  authBox.addEventListener('submit', async function (e) {
    e.preventDefault();
    var form = e.target, err = form.querySelector('.pred-form__error'), btn = form.querySelector('.pred-submit');
    function field(n) { var el = form.elements.namedItem(n); return el ? el.value : ''; }
    var data = { handle: field('handle'), password: field('password'), name: field('name'), country: field('country') };
    err.textContent = '';
    btn.disabled = true;
    try {
      state.me = authTab === 'register' ? await api.register(data) : await api.login(data);
      await loadMine();
      state.drafts = {};
      renderGrid();
      await refreshBoard();
      renderAuth();
    } catch (ex) {
      err.textContent = (ex && ex.message) || 'حدث خطأ، حاول مرة أخرى.';
      btn.disabled = false;
    }
  });

  // ------------------------------------------------------------------ leaderboard + user dialog
  function renderBoard() {
    var rows = state.board;
    if (!rows.length) {
      boardList.innerHTML = '<li class="pred-board__empty">لا يوجد متوقعون بعد. سجّل حسابك وكن أول من يتصدر الترتيب!</li>';
      return;
    }
    boardList.innerHTML = rows.slice(0, 50).map(function (r) {
      var c = country(r.user.country), me = state.me && state.me.handle === r.user.handle;
      var tier = r.rank === 1 ? ' is-gold' : (r.rank === 2 ? ' is-silver' : (r.rank === 3 ? ' is-bronze' : ''));
      return `<li><button type="button" class="pred-row${tier}${me ? ' is-me' : ''}" data-user="${esc(r.user.handle)}">
        <span class="pred-row__rank">${r.rank === 1 ? '<span class="pred-crown" aria-hidden="true">👑</span>' : ''}${r.rank}</span>
        <span class="pred-row__who">
          <b>${esc(r.user.name)}${me ? '<em>أنت</em>' : ''}</b>
          <small><span dir="ltr">@${esc(r.user.handle)}</span>${c ? ' · ' + c[2] + ' ' + esc(c[1]) : ''}</small>
          <small>${r.exact} نتيجة صحيحة · ${r.winner} فائز صحيح</small>
        </span>
        <span class="pred-row__pts">${r.points}<small>نقطة</small></span>
      </button></li>`;
    }).join('');
  }
  async function refreshBoard() {
    try { state.board = await leaderboard(); } catch (e) { console.warn('[PX League] leaderboard:', e); }
    renderBoard();
    if (state.me) renderProfile();
  }
  boardList.addEventListener('click', function (e) {
    var row = e.target.closest('[data-user]');
    if (row) openUser(row.getAttribute('data-user'));
  });

  var dialog = null;
  function ensureDialog() {
    if (dialog) return dialog;
    dialog = document.createElement('dialog');
    dialog.className = 'pred-dialog';
    dialog.setAttribute('aria-labelledby', 'pred-dialog-title');
    document.body.appendChild(dialog);
    dialog.addEventListener('click', function (e) {
      if (e.target === dialog || e.target.closest('[data-close]')) closeDialog();
    });
    return dialog;
  }
  function closeDialog() { if (!dialog) return; if (dialog.close) dialog.close(); else dialog.removeAttribute('open'); }
  function histHtml(p, isMe) {
    var m = p.match, pts = pointsFor(p), r = results[m.id];
    var hidden = !isMe && !startedAt(m.ts);               // others' picks stay private until kickoff
    var kind = pts == null ? 'pending' : (pts === POINTS_EXACT ? 'exact' : (pts === POINTS_WINNER ? 'winner' : 'miss'));
    return `<li class="is-${kind}">
      <div class="pred-hist__match">
        <b>${esc(m.home)} <span>ضد</span> ${esc(m.away)}</b>
        <small>${esc(m.league)} · ${esc(kickoffText(m.ts))}</small>
        <small>${hidden ? 'التوقع مخفي حتى بداية المباراة' : 'التوقع: ' + scoreText(p.h, p.a)}${r ? ' · النتيجة: ' + scoreText(r[0], r[1]) : (startedAt(m.ts) ? ' · بانتظار النتيجة' : '')}</small>
      </div>
      <span class="pred-hist__pts">${pts == null ? '—' : '+' + pts}</span>
    </li>`;
  }
  async function openUser(handle) {
    var row = null;
    state.board.forEach(function (r) { if (r.user.handle === handle) row = r; });
    if (!row) return;
    var d = ensureDialog(), c = country(row.user.country), isMe = !!(state.me && state.me.handle === handle);
    d.innerHTML = `
      <div class="pred-dialog__head">
        <span class="pred-avatar" aria-hidden="true">${esc(initial(row.user.name))}</span>
        <div>
          <b id="pred-dialog-title">${esc(row.user.name)}</b>
          <small><span dir="ltr">@${esc(row.user.handle)}</span>${c ? ' · ' + c[2] + ' ' + esc(c[1]) : ''} · المركز ${row.rank} · ${row.points} نقطة</small>
        </div>
        <button type="button" class="pred-dialog__close" data-close aria-label="إغلاق">×</button>
      </div>
      <div class="pred-dialog__body"><div class="px-loader" role="status"><span class="px-spinner"></span><span>جاري التحميل...</span></div></div>`;
    if (d.showModal) { if (!d.open) d.showModal(); } else d.setAttribute('open', '');
    var body = d.querySelector('.pred-dialog__body');
    try {
      var preds = (row.preds || await api.predictions(handle)).slice().sort(function (x, y) { return y.match.ts - x.match.ts; });
      body.innerHTML = preds.length
        ? `<ul class="pred-hist">${preds.map(function (p) { return histHtml(p, isMe); }).join('')}</ul>`
        : '<p class="pred-board__empty">لا توجد توقعات بعد.</p>';
    } catch (e) {
      body.innerHTML = '<p class="pred-board__empty">تعذّر تحميل التوقعات.</p>';
    }
  }

  // ------------------------------------------------------------------ fetching
  async function fetchDay(iso) {
    var url = WORKER_BASE_URL + '/api/matches/matches_date_get/' + iso + '/' + encodeURI(MATCH_FILTERS) + '/D/60';
    for (var attempt = 1; attempt <= 2; attempt++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 10000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var json = await res.json();
        return (Array.isArray(json && json.data) ? json.data : [])
          .map(function (r) { return parseMatch(r, iso); })
          .filter(function (m) { return m.id && m.ts; });
      } catch (err) {
        if (attempt === 2) throw err;
        await new Promise(function (r) { setTimeout(r, 1200); });
      } finally {
        clearTimeout(timer);
      }
    }
    return [];
  }
  async function loadMatches() {
    state.loading = true;
    state.error = '';
    renderGrid();
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      state.loading = false;
      state.error = 'لم يتم ضبط رابط خادم المباريات.';
      renderGrid();
      return;
    }
    var days = [];
    for (var i = 0; i < DAYS_AHEAD; i++) days.push(dayKey(Date.now() + i * 864e5));
    var settled = await Promise.allSettled(days.map(fetchDay));
    var byId = {}, ok = 0;
    settled.forEach(function (s) {
      if (s.status !== 'fulfilled') return;
      ok++;
      s.value.forEach(function (m) { byId[m.id] = m; });
    });
    var list = Object.keys(byId).map(function (k) { return byId[k]; });
    recordResults(list);
    var featured = list.filter(function (m) { return LEAGUES.indexOf(m.leagueId) !== -1; });
    list = featured.length ? featured : list;
    list.sort(function (x, y) {                            // open matches first, then by kickoff
      return (isLocked(x) - isLocked(y)) || (x.ts - y.ts);
    });
    state.matches = list;
    state.loading = false;
    state.error = ok ? '' : 'تعذّر تحميل المباريات حاليًا.';
    renderFilters();
    renderGrid();
    await backfillResults(days);
    refreshBoard();
  }
  // Final scores for older predicted matches (local mode; a backend scores on the server).
  async function backfillResults(loadedDays) {
    if (!isLocal) return;
    var users = await api.listUsers(), dates = {};
    for (var i = 0; i < users.length; i++) {
      (await api.predictions(users[i].handle)).forEach(function (p) {
        var m = p.match;
        if (m && !results[m.id] && m.feedDate && loadedDays.indexOf(m.feedDate) === -1 && Date.now() > m.ts + 2 * 3600e3) dates[m.feedDate] = 1;
      });
    }
    var list = Object.keys(dates).sort().reverse().slice(0, 7);
    if (!list.length) return;
    await Promise.allSettled(list.map(function (d) { return fetchDay(d).then(recordResults); }));
  }

  // Lock cards the moment their match kicks off (checked every 30 s).
  setInterval(function () {
    if (state.loading) return;
    var changed = state.matches.some(function (m) { return lockedAtRender[m.id] === false && isLocked(m); });
    if (changed) renderGrid();
  }, 30000);

  // ------------------------------------------------------------------ init
  (async function init() {
    try { state.me = await api.me(); } catch (e) { state.me = null; }
    await loadMine();
    renderAuth();
    refreshBoard();
    loadMatches();
  })();
})();
//

//
(function () {
  'use strict';
  if (location.pathname !== '/p/match.html') return;   // client-side route guard

  var WORKER_BASE_URL = window.PXL_WORKER_BASE_URL || '';
  var TEAM_LOGO_BASE = 'https://imgs.ysscores.com/teams/128/';
  var LEAGUE_LOGO_BASE = 'https://imgs.ysscores.com/championship/64/';
  var LIVE_WINDOW_MS = 3.5 * 60 * 60 * 1000;
  var REFRESH_MS = 10 * 1000;                                 // while live (Worker edge TTL for match_info: 15 s)
  var PRE_MATCH_MS = 30 * 1000;                               // last 30 min before kick-off

  var page = document.getElementById('match-page');
  if (!page) return;
  var hero = document.getElementById('match-hero');
  var panels = { events: document.getElementById('match-tab-events'), lineups: document.getElementById('match-tab-lineups') };
  var tabs = Array.prototype.slice.call(page.querySelectorAll('.match-tab'));

  // ------------------------------------------------------------------ helpers
  var ESC = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g, function (c) { return ESC[c]; }); }
  function wait(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }
  function imageUrl(base, file) {
    var f = file ? String(file).trim() : '';
    return /^[\w.-]+\.(png|jpe?g|webp|gif|svg)$/i.test(f) ? base + encodeURIComponent(f) : '';
  }
  function nameOf(x) {                                         // player / referee objects or plain strings
    if (!x) return '';
    if (typeof x === 'string') return x;
    return x.short_title || x.title || x.full_title || '';
  }
  function cairo(unix, opts) {
    try { return new Intl.DateTimeFormat(window.pxlLocale(), Object.assign({ timeZone: 'Africa/Cairo' }, opts)).format(new Date(unix * 1000)); }
    catch (e) { return ''; }
  }
  function cairoTime(unix) {
    if (!unix) return '--:--';
    return new Intl.DateTimeFormat('en-GB', { timeZone: 'Africa/Cairo', hour: '2-digit', minute: '2-digit', hour12: false }).format(new Date(unix * 1000));
  }
  function api(kind, id) { return WORKER_BASE_URL + '/api/matches/' + kind + '/' + encodeURIComponent(id) + '/D/60'; }
  // Write markup only when it changed. Most 30 s polls return identical data; skipping the
  // write avoids rebuilding nodes, re-decoding logos, reflow and lost hover/focus/scroll state.
  function setHtml(el, html) {
    if (el._pxHtml === html) return false;
    el.innerHTML = html;
    el._pxHtml = html;
    return true;
  }

  async function fetchJson(url, attempts) {
    for (var i = 1; ; i++) {
      var ctrl = new AbortController();
      var timer = setTimeout(function () { ctrl.abort(); }, 10000);
      try {
        var res = await fetch(url, { headers: { Accept: 'application/json' }, cache: 'no-store', signal: ctrl.signal });
        if (!res.ok) throw new Error('HTTP ' + res.status);
        var json = await res.json();
        if (json && json.status === false) throw new Error(json.message || 'API status false');
        return json && json.data != null ? json.data : json;
      } catch (err) {
        if (i >= attempts) throw err;
        await wait(1000 * i);
      } finally {
        clearTimeout(timer);
      }
    }
  }

  // Shared rule (SETTINGS script at the top): live === 1 first (inside the kick-off window),
  // then 0 upcoming, 4 finished, other codes live near kick-off.
  function statusOf(raw) { return window.pxlMatchStatus(raw); }
  // Match clock -> minute text: shared helper pxlLive.minute (SETTINGS script at the top).
  // Kept as a local name for normalize(); returns '' for half-time (status 2) and unknown codes.
  function liveMinute(status, seconds) { return window.pxlLive.minute(status, seconds); }

  // ------------------------------------------------------------------ icons
  var I = {
    ball: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="m12 7 4 3-1.5 5h-5L8 10z" fill="currentColor"/></svg>',
    sub: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path class="ev__in" d="M7 20V8m0 0-4 4m4-4 4 4"/><path class="ev__out" d="M17 4v12m0 0 4-4m-4 4-4-4"/></svg>',
    cal: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/></svg>',
    pin: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 22s7-6.1 7-12a7 7 0 0 0-14 0c0 5.9 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/></svg>',
    whistle: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><circle cx="9" cy="14" r="6"/><path d="M13 9.5 21 6v4l-6.5 2"/></svg>',
    tv: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><rect x="2" y="7" width="20" height="14" rx="2"/><path d="m17 2-5 5-5-5"/></svg>',
    mic: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z"/><path d="M19 11a7 7 0 0 1-14 0M12 18v4"/></svg>'
  };
  function cardIcon(kind) { return '<span class="card-ico card-ico--' + kind + '"></span>'; }

  // ------------------------------------------------------------------ normalize (data layer)
  // normalize(info, ev, lu) is the ONLY code that reads raw ysscores shapes. The renderers
  // below use its result only. Raw shapes (verified on match 5702737, 2026-11-20):
  //   info = match_info.data      events / lineup / statics are FLAGS (0|1), stats are in
  //                               statics_match, shootout in penalties[teamId] = [{playerId: 0|1}]
  //   ev   = matches_event.data   event / lineup / static are the flags, the list is "events",
  //                               stats in statics, shootout in match_penalties[teamId]
  //   lu   = matches_lineup.data  OBJECT: lu["0"] = header (home_team / away_team = numeric ids,
  //                               *_team_info, *_formation, *_coach), lu.lineup[teamId] = { lineup, substitutions }
  // Team ids are numbers in objects but STRING keys in maps (statics, penalties, lineup, agg_result).
  // Any argument may be null (failed / not requested): the result then has empty parts.
  var PLAYER_IMG_BASE = 'https://imgs.ysscores.com/player/128/';   // verified: player/128/{image} serves image/png
  var PLACEHOLDER_PLAYER_ID = 9965324011;                       // "غير معروف", shared by many entries
  var EVENT_KIND = { 1: 'goal', 4: 'own_goal', 5: 'pen_goal', 2: 'yellow', 3: 'red', 8: 'sub' };   // others (21, 22...) ignored
  var ROW_ORDER = ['G', 'D', 'M', 'F', 'S'];                    // lineup item.position = pitch row (NOT player.position)

  function num(v) {                                            // "6.8" -> 6.8, null/''/garbage -> null
    if (v === null || v === undefined || v === '') return null;
    var n = Number(v);
    return isFinite(n) ? n : null;
  }
  function parseMaybeJson(v) {                                 // ex_time / score_time may be '[{"1":83}]'
    if (typeof v !== 'string') return v ?? null;
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  function person(p) {
    if (!p || typeof p !== 'object') return null;
    var id = num(p.id ?? p.row_id);
    var name = p.short_title || p.title || p.full_title || '';
    return { id: id, name: name, placeholder: id === PLACEHOLDER_PLAYER_ID || name === 'غير معروف' };
  }
  function team(t, qualified, header, side) {
    t = t || {};
    return {
      id: num(t.row_id),
      name: t.full_title || t.title || '',
      short: t.title || t.full_title || '',
      logo: imageUrl(TEAM_LOGO_BASE, t.image),
      qualified: Number(qualified) === 1,
      formation: header?.[side + '_formation'] || '',
      coach: person(header?.[side + '_coach'])?.name || ''
    };
  }
  function halfScore(arr) {                                    // [{home_team:"6296",home_scores:"0"},{away_team:"10077",away_scores:"0"}]
    if (!Array.isArray(arr)) return null;
    var h = arr.find(function (x) { return x?.home_scores != null; });
    var a = arr.find(function (x) { return x?.away_scores != null; });
    return h && a ? { home: num(h.home_scores) ?? 0, away: num(a.away_scores) ?? 0 } : null;
  }
  // Shootout. Many kicks share the placeholder player_id, so entries are NEVER keyed by player id:
  // the array order is the kick order, total = sum of scores.
  function shootoutSide(evList, infoList) {
    var kicks = [];
    if (Array.isArray(evList) && evList.length) {               // matches_event: {player_id, player_name, score}
      kicks = evList.map(function (k) { return { player: person(k?.player_name), scored: Number(k?.score) === 1 }; });
    } else if (Array.isArray(infoList) && infoList.length) {    // match_info: [{ "<playerId>": 0|1 }]
      kicks = infoList.map(function (k) {
        var vals = k && typeof k === 'object' ? Object.values(k) : [];
        return { player: null, scored: Number(vals[0]) === 1 };
      });
    }
    return { kicks: kicks, total: kicks.reduce(function (s, k) { return s + (k.scored ? 1 : 0); }, 0) };
  }
  function stats(map, id) {
    var s = map && typeof map === 'object' ? map[String(id)] : null;
    if (!s || typeof s !== 'object') return null;
    return { shots: num(s.total_shots), fouls: num(s.fouls), offsides: num(s.offsides), possession: num(s.ball_possession), xg: num(s.xg) };
  }
  function minuteLabel(m, plus) { return m == null ? '' : m + (plus > 0 ? '+' + plus : '') + "'"; }
  function normEvents(list, homeId, awayId) {
    if (!Array.isArray(list)) return [];
    return list.slice().sort(function (a, b) {                 // newest first: minute, added time, event id
      return (num(b?.time_minute) || 0) - (num(a?.time_minute) || 0) ||
        (num(b?.time_plus) || 0) - (num(a?.time_plus) || 0) ||
        (num(b?.event_id) || 0) - (num(a?.event_id) || 0);
    }).map(function (e) {
      var type = Number(e?.type);
      if (type === 100) {                                      // phase marker: no player, its time_plus is not a minute
        return { id: num(e.event_id), kind: 'phase', phase: Number(e.status), side: '' };
      }
      var kind = EVENT_KIND[type];
      if (!kind) return null;
      if (kind === 'red' && Number(e.status) === 7) kind = 'second_yellow';
      // Side from the EVENT's team_id only (player_name.team_id can be another club: 162418 vs 6296)
      var tid = String(e.team_id ?? '');
      var side = tid === String(homeId) ? 'home' : tid === String(awayId) ? 'away' : '';
      if (!side) return null;
      var m = num(e.time_minute), plus = num(e.time_plus) || 0;
      var p = person(e.player_name), a = person(e.assist_player_name);
      var out = { id: num(e.event_id), kind: kind, side: side, minute: m, plus: plus, minuteText: minuteLabel(m, plus) };
      if (kind === 'sub') {                                    // player_name = OUT, assist_player_name = IN
        out.playerOut = p; out.playerIn = a; out.injury = Number(e.status) === 9;
      } else {
        out.player = p; out.assist = a;
      }
      return out;
    }).filter(Boolean);
  }
  function lineupPlayer(item, bench) {
    var pl = item?.player || {};
    var p = person(pl) || { id: null, name: '', placeholder: true };
    var subAt = num(item?.substitute_time), subPlus = num(item?.substitute_plus) || 0;
    return {
      id: p.id, name: p.name, placeholder: p.placeholder,
      number: pl.player_number ?? '',
      role: pl.position || '',                                 // real position ("GK", "CM"...), display only
      image: imageUrl(PLAYER_IMG_BASE, pl.image),
      country: pl.country?.title || '',
      row: item?.position || '',                               // G|D|M|F|S
      slot: num(item?.formation_position) || 0,
      captain: Number(item?.captain) === 1,
      rating: item?.rating ? String(item.rating) : '',
      goals: num(item?.goal) || 0, ownGoals: num(item?.own_goal) || 0, assists: num(item?.assist) || 0,
      yellow: Number(item?.yellow) === 1, red: Number(item?.red) === 1,
      subbedOff: !bench && Number(item?.substitute) === 1,
      cameOn: bench && subAt != null,
      subMinute: subAt != null ? minuteLabel(subAt, subPlus) : ''
    };
  }
  function teamLineup(block, injured) {
    if (!block || typeof block !== 'object') return null;
    var starters = (Array.isArray(block.lineup) ? block.lineup : []).map(function (x) { return lineupPlayer(x, false); });
    var bench = (Array.isArray(block.substitutions) ? block.substitutions : []).map(function (x) { return lineupPlayer(x, true); });
    if (!starters.length) return null;
    // Pitch rows by item.position in G, D, M, F, S order, sorted by formation_position.
    // Not derived from the formation string (4-2-3-1 = D4 M2 F3 S1, 4-3-3 has no S row).
    var known = starters.every(function (p) { return ROW_ORDER.indexOf(p.row) !== -1; });
    var rows = known ? ROW_ORDER.map(function (r) {
      return starters.filter(function (p) { return p.row === r; }).sort(function (a, b) { return a.slot - b.slot; });
    }).filter(function (r) { return r.length; }) : null;
    return {
      starters: starters, bench: bench, rows: rows,
      injured: (Array.isArray(injured) ? injured : []).map(function (x) {
        return { name: person(x?.player)?.name || '', note: [x?.type_name, x?.injury].filter(Boolean).join(' - ') };
      }).filter(function (x) { return x.name; })
    };
  }

  function normalize(info, ev, lu) {
    var header = lu?.['0'] || null;
    var src = info || ev || header || {};
    var homeRaw = info?.home_team || ev?.home_team || header?.home_team_info || {};
    var awayRaw = info?.away_team || ev?.away_team || header?.away_team_info || {};
    var home = team(homeRaw, src.home_qualified, header, 'home');
    var away = team(awayRaw, src.away_qualified, header, 'away');
    var hk = String(home.id ?? header?.home_team ?? ''), ak = String(away.id ?? header?.away_team ?? '');
    var st = statusOf(src);
    var champ = src.championship || {};
    var cc = Array.isArray(info?.channel_commm) && info.channel_commm.length ? info.channel_commm[0] : {};

    var aggRaw = info?.agg_result || ev?.agg_result;
    var agg = aggRaw && typeof aggRaw === 'object' && (aggRaw[hk] != null || aggRaw[ak] != null) ? {
      home: num(aggRaw[hk]) ?? 0,
      away: num(aggRaw[ak]) ?? 0,
      winner: String(aggRaw.win_team ?? '') === hk ? 'home' : String(aggRaw.win_team ?? '') === ak ? 'away'
        : home.qualified ? 'home' : away.qualified ? 'away' : ''
    } : null;
    var leg = info?.return;
    var firstLeg = leg && typeof leg === 'object' && leg.match_id ? {
      id: num(leg.match_id), home: leg.home_team || '', away: leg.away_team || '',       // home/away swapped vs this match
      score: { home: num(leg.home_scores) ?? 0, away: num(leg.away_scores) ?? 0 }
    } : null;

    var ph = shootoutSide(ev?.match_penalties?.[hk], info?.penalties?.[hk]);
    var pa = shootoutSide(ev?.match_penalties?.[ak], info?.penalties?.[ak]);
    var penalties = ph.kicks.length || pa.kicks.length ? { home: ph, away: pa } : null;

    var statMap = ev?.statics && typeof ev.statics === 'object' ? ev.statics
      : info?.statics_match && typeof info.statics_match === 'object' ? info.statics_match : null;
    var sh = stats(statMap, hk), sa = stats(statMap, ak);

    var ts = num(src.match_timestamp) || 0;                    // UTC seconds; match_time (UTC+3) is never used
    return {
      id: num(src.match_id),
      status: st,                                              // 'upcoming' | 'live' | 'finished' | 'other'
      statusCode: num(src.status),
      live: st === 'live',
      phase: st === 'live' ? window.pxlLive.phase(info || src, true) : '',   // '1h' | 'ht' | '2h' | ''
      clock: st === 'live' && info ? window.pxlLive.clock(info) : null,       // local tick between refreshes
      minute: st === 'live' ? liveMinute(info?.status, info?.minutes) : '',
      kickoff: ts,
      exTime: parseMaybeJson(src.ex_time),
      scoreTime: parseMaybeJson(src.score_time),
      league: { id: num(src.championship_id), title: champ.title || '', logo: imageUrl(LEAGUE_LOGO_BASE, champ.image) },
      round: info?.round || '',
      venue: info?.Stadium || '',
      referee: nameOf(info?.referees),
      channel: cc.channel_name || '',
      commentator: cc.commentator_name || '',
      home: home,
      away: away,
      score: {
        home: num(src.home_scores) ?? 0,                       // THIS match only (never the aggregate)
        away: num(src.away_scores) ?? 0,
        ht: halfScore(ev?.fh_scores),
        sh: halfScore(ev?.sh_scores)
      },
      agg: agg,
      firstLeg: firstLeg,
      penalties: penalties,
      stats: sh || sa ? { home: sh, away: sa } : null,
      events: normEvents(ev?.events, hk, ak),
      lineup: {
        home: teamLineup(lu?.lineup?.[hk], lu?.lineup_injureds?.[hk]),
        away: teamLineup(lu?.lineup?.[ak], lu?.lineup_injureds?.[ak])
      },
      stream: info?.stream || null,
      hasEvents: Number(info?.events) === 1,
      hasLineup: Number(info?.lineup) === 1
    };
  }
  window.pxlNormalizeMatch = normalize;

  // ------------------------------------------------------------------ hero
  function teamInner(t) {
    return `<span class="mh__logo">${t.logo ? `<img src="${esc(t.logo)}" alt="${esc(t.name)}" decoding="async" referrerpolicy="no-referrer" onerror="this.replaceWith(document.createTextNode(''))">` : `<span>${esc(t.name.slice(0, 2))}</span>`}</span>
        <span class="mh__name">${esc(t.name)}</span>`;
  }
  // The hero skeleton is built once; each poll then patches only the region that changed
  // (in practice: the score/minute in .mh__center). Logos are never re-created.
  var heroParts = null;
  function heroShell() {
    if (heroParts && hero.contains(heroParts.center)) return heroParts;
    hero.innerHTML = '<div class="mh__league"></div><div class="mh__teams"><div class="mh__team"></div><div class="mh__center"></div><div class="mh__team"></div></div><div class="mh__meta-slot"></div>';
    hero._pxHtml = null;                                       // hero no longer holds loader/message markup
    var teams = hero.querySelectorAll('.mh__team');
    heroParts = {
      league: hero.querySelector('.mh__league'), home: teams[0], away: teams[1],
      center: hero.querySelector('.mh__center'), meta: hero.querySelector('.mh__meta-slot')
    };
    return heroParts;
  }
  function pair(s) { return s ? s.home + ' - ' + s.away : ''; }
  function penaltiesText(n) { return n.penalties ? n.penalties.home.total + ' - ' + n.penalties.away.total : ''; }
  function renderHero(n) {
    var st = n.status;
    var center = st === 'upcoming' || st === 'other'
      ? `<span class="mh__time">${esc(cairoTime(n.kickoff))}</span>`
      : `<span class="mh__score"><span>${esc(n.score.home)}</span><span class="sep">-</span><span>${esc(n.score.away)}</span></span>`;
    var badge = st === 'live'
      ? `<span class="mh__badge mh__badge--live">${window.pxlLive.badge(n.phase, n.clock)}</span>`   // "استراحة" at half-time, same live style
      : `<span class="mh__badge">${st === 'finished' ? 'انتهت' : st === 'upcoming' ? 'لم تبدأ' : 'غير محدد'}</span>`;
    // Extra lines reuse the existing .mh__ht style (no new markup classes / CSS)
    var lines = [];
    if (st !== 'upcoming' && n.score.ht) lines.push('الشوط الأول: ' + pair(n.score.ht));
    if (n.penalties) lines.push('ركلات الترجيح: ' + penaltiesText(n));
    if (n.agg) {
      var q = n.agg.winner ? n[n.agg.winner].name : '';
      lines.push('مجموع المباراتين: ' + pair(n.agg) + (q ? ' · تأهل ' + q : ''));
    }
    var ts = n.kickoff;
    var meta = [
      ts ? [I.cal, cairo(ts, { weekday: 'long', day: 'numeric', month: 'long' }) + ' · ' + cairoTime(ts)] : null,
      n.venue ? [I.pin, n.venue] : null,
      n.referee ? [I.whistle, 'الحكم: ' + n.referee] : null,
      n.channel ? [I.tv, n.channel] : null,
      n.commentator ? [I.mic, n.commentator] : null
    ].filter(Boolean);

    var cls = 'match-hero' + (st === 'live' ? ' match-hero--live' : '');
    if (hero.className !== cls) hero.className = cls;
    var parts = heroShell();
    setHtml(parts.league, `${n.league.logo ? `<img src="${esc(n.league.logo)}" alt="" decoding="async" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}
        <b>${esc(n.league.title)}</b>${n.round ? `<span>· ${esc(n.round)}</span>` : ''}`);
    setHtml(parts.home, teamInner(n.home));
    setHtml(parts.center, `${center}${badge}${lines.map(function (l) { return `<span class="mh__ht">${esc(l)}</span>`; }).join('')}`);
    setHtml(parts.away, teamInner(n.away));
    setHtml(parts.meta, meta.length ? `<ul class="mh__meta">${meta.map(function (x) { return `<li>${x[0]}<span>${esc(x[1])}</span></li>`; }).join('')}</ul>` : '');

    if (n.home.name && n.away.name) updateSeo(n);
    return st;
  }

  // SEO for /p/match.html?id=: title, description, canonical WITH the ?id= (one indexable
  // URL per match) and SportsEvent structured data. pxlSeo (head script) only writes the
  // tags / JSON-LD when they changed, so the polls cost nothing.
  function updateSeo(n) {
    if (!window.pxlSeo || !/^\d{1,12}$/.test(matchId)) return;
    var st = n.status, ts = n.kickoff, home = n.home.name, away = n.away.name;
    var league = n.league.title;
    var when = ts ? cairo(ts, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }) + ' الساعة ' + cairoTime(ts) : '';
    var score = st === 'live' || st === 'finished' ? n.score.home + ' - ' + n.score.away : '';
    var name = home + ' ضد ' + away;
    var title = name + (score ? ' (' + score + ')' : '') + (league ? ' - ' + league : '') + ' | PX League';
    var lead = st === 'live' ? 'مباشر: مباراة ' : st === 'finished' ? 'نتيجة مباراة ' : 'موعد مباراة ';
    var desc = lead + home + ' و' + away + (league ? ' في ' + league : '')
      + (when ? '، ' + when + ' بتوقيت القاهرة' : '') + (n.venue ? '، على ملعب ' + n.venue : '')
      + '. الأحداث والتشكيلات لحظة بلحظة على PX League.';
    var url = (window.PXL_SITE_URL || location.origin).replace(/\/+$/, '') + '/p/match.html?id=' + matchId;
    window.pxlSeo.set({ title: title, description: desc, url: url, image: n.home.logo || n.away.logo });

    var homeTeam = { '@type': 'SportsTeam', name: home };
    var awayTeam = { '@type': 'SportsTeam', name: away };
    if (n.home.logo) homeTeam.logo = n.home.logo;
    if (n.away.logo) awayTeam.logo = n.away.logo;
    var ld = {
      '@context': 'https://schema.org',
      '@type': 'SportsEvent',
      name: name,
      description: desc,
      url: url,
      sport: 'Soccer',
      eventStatus: 'https://schema.org/EventScheduled',
      eventAttendanceMode: 'https://schema.org/OfflineEventAttendanceMode',
      location: { '@type': 'Place', name: n.venue || league || name },
      homeTeam: homeTeam,
      awayTeam: awayTeam,
      competitor: [homeTeam, awayTeam]
    };
    if (ts) ld.startDate = new Date(ts * 1000).toISOString();
    if (league) ld.superEvent = { '@type': 'SportsEvent', name: league };
    var images = [n.home.logo, n.away.logo].filter(Boolean);
    if (images.length) ld.image = images;
    window.pxlSeo.jsonLd('pxl-ld-match', ld);
  }

  // ------------------------------------------------------------------ events tab
  // Phase markers (type 100) by status. 11 is not labelled: on 5702737 it sits between the end
  // of 90' and full-time of a match that went straight to penalties, so "extra time" is unproven.
  var PERIODS = { 1: 'انطلاق المباراة', 2: 'نهاية الشوط الأول', 3: 'بداية الشوط الثاني', 5: 'نهاية الوقت الأصلي', 4: 'نهاية المباراة' };
  function eventHtml(e, n) {
    if (e.kind === 'phase') {
      var label = PERIODS[e.phase];
      if (!label) return '';
      var score = '';
      if (e.phase === 2) score = pair(n.score.ht);
      if (e.phase === 4) score = pair(n.score) + (n.penalties ? ' (ر.ت ' + penaltiesText(n) + ')' : '');
      return `<li class="ev ev--period"><span class="ev__period">${esc(label)}${score ? `<b>${esc(score)}</b>` : ''}</span></li>`;
    }
    var icon = '', title = '', sub = '', cls = '';
    if (e.kind === 'sub') {
      icon = I.sub;
      title = e.playerIn?.name || e.playerOut?.name || '';      // player coming on
      sub = (e.playerIn && e.playerOut ? 'خروج: ' + e.playerOut.name : 'تبديل') + (e.injury ? ' (إصابة)' : '');
    } else {
      title = e.player?.name || '';
      if (e.kind === 'goal' || e.kind === 'own_goal' || e.kind === 'pen_goal') {
        cls = ' ev--goal'; icon = I.ball;
        sub = e.kind === 'own_goal' ? 'هدف عكسي' : e.kind === 'pen_goal' ? 'ركلة جزاء' : e.assist ? 'صناعة: ' + e.assist.name : 'هدف';
      } else if (e.kind === 'yellow') {
        icon = cardIcon('y'); sub = 'بطاقة صفراء';
      } else {
        var second = e.kind === 'second_yellow';
        icon = cardIcon(second ? 'yr' : 'r'); sub = second ? 'إنذار ثانٍ' : 'بطاقة حمراء';
      }
    }
    if (!title) return '';
    return `<li class="ev ev--${e.side}${cls}">
        <div class="ev__body"><span class="ev__icon">${icon}</span><span class="ev__txt"><b>${esc(title)}</b>${sub ? `<small>${esc(sub)}</small>` : ''}</span></div>
        <span class="ev__min" dir="ltr">${esc(e.minuteText)}</span>
      </li>`;
  }
  // Events are newest first. When the previous list is an exact tail of the new one (the
  // normal live case: a goal/card was added), only the new <li> items are inserted at the top.
  var lastEvItems = null;
  function sameItems(a, b, offset) {
    for (var i = 0; i < b.length; i++) if (a[i + offset] !== b[i]) return false;
    return true;
  }
  function renderEvents(n) {
    var items = n.events.map(function (e) { return eventHtml(e, n); }).filter(Boolean);
    var el = panels.events;
    if (!items.length) {
      lastEvItems = null;
      setHtml(el, `<div class="match-message"><span>${n.status === 'upcoming' ? 'لم تبدأ المباراة بعد، ستظهر الأحداث هنا فور انطلاقها.' : 'لا توجد أحداث مسجلة لهذه المباراة.'}</span></div>`);
      return;
    }
    var full = '<ol class="ev-list">' + items.join('') + '</ol>';
    var ol = el.querySelector('.ev-list');
    var added = lastEvItems ? items.length - lastEvItems.length : -1;
    if (ol && added > 0 && sameItems(items, lastEvItems, added)) {
      ol.insertAdjacentHTML('afterbegin', items.slice(0, added).join(''));
      el._pxHtml = full;
    } else {
      setHtml(el, full);                                       // identical -> no-op
    }
    lastEvItems = items;
  }

  // ------------------------------------------------------------------ lineups tab
  function tagsHtml(p) {
    var t = '';
    for (var i = 0; i < Math.min(p.goals, 3); i++) t += '<span class="tag-goal">⚽</span>';
    if (p.red) t += cardIcon('r');
    else if (p.yellow) t += cardIcon('y');
    if (p.subbedOff) t += `<span class="tag-sub" title="تم استبداله">▼${p.subMinute ? ` <span dir="ltr">${esc(p.subMinute)}</span>` : ''}</span>`;
    if (p.cameOn) t += `<span class="tag-sub" title="دخل بديلًا">▲ <span dir="ltr">${esc(p.subMinute)}</span></span>`;
    return t;
  }
  function playerChip(p, isGk) {
    return `<div class="pl${isGk ? ' pl--gk' : ''}">
        <span class="pl__num">${esc(p.number)}${p.rating ? `<span class="pl__rating">${esc(p.rating)}</span>` : ''}${p.captain ? '<span class="pl__cap">C</span>' : ''}</span>
        <span class="pl__name">${esc(p.name)}</span>
        <span class="pl__tags">${tagsHtml(p)}</span>
      </div>`;
  }
  function pitchHtml(rows) {                                   // rows from normalize(): G, D, M, F, S
    if (!rows || !rows.length || rows[0][0].row !== 'G') return '';   // unknown shape: list only
    return `<div class="pitch">${rows.map(function (r, idx) {
      return `<div class="pitch__line">${r.map(function (p) { return playerChip(p, idx === 0); }).join('')}</div>`;
    }).join('')}</div>`;
  }
  function listHtml(players) {
    return `<ul class="lu-list">${players.map(function (p) {
      return `<li><span class="n">${esc(p.number || '-')}</span><span>${esc(p.name)}</span>
        <span class="meta">${tagsHtml(p)}${p.rating ? `<span class="r">${esc(p.rating)}</span>` : ''}</span></li>`;
    }).join('')}</ul>`;
  }
  function teamLineupHtml(n, side) {
    var L = n.lineup[side], t = n[side];
    if (!L) return '';
    return `<section class="lu-team">
        <div class="lu-head">${t.logo ? `<img src="${esc(t.logo)}" alt="" referrerpolicy="no-referrer" onerror="this.remove()">` : ''}<span>${esc(t.name)}</span>${t.formation ? `<span class="lu-formation">${esc(t.formation)}</span>` : ''}</div>
        ${pitchHtml(L.rows) || listHtml(L.starters)}
        ${t.coach ? `<p class="lu-coach">المدرب: <b>${esc(t.coach)}</b></p>` : ''}
        ${L.bench.length ? `<h3 class="lu-sub-title">البدلاء</h3>${listHtml(L.bench)}` : ''}
        ${L.injured.length ? `<h3 class="lu-sub-title">الغيابات</h3><ul class="lu-list">${L.injured.map(function (x) {
          return `<li><span class="n">✚</span><span>${esc(x.name)}</span><span class="meta">${esc(x.note)}</span></li>`;
        }).join('')}</ul>` : ''}
      </section>`;
  }
  function renderLineups(n) {
    var html = teamLineupHtml(n, 'home') + teamLineupHtml(n, 'away');
    setHtml(panels.lineups, html
      ? `<div class="lu-grid">${html}</div>`
      : '<div class="match-message"><span>لم يتم الإعلان عن التشكيلات بعد.</span></div>');
  }

  // ------------------------------------------------------------------ states
  function loader(el, text) {
    setHtml(el, `<div class="px-loader" role="status"><span class="px-spinner"></span>${text ? `<span>${esc(text)}</span>` : ''}</div>`);
  }
  function message(el, text, retry) {
    if (!setHtml(el, `<div class="match-message"><span>${esc(text)}</span>${retry ? '<button class="px-retry" type="button">إعادة المحاولة</button>' : ''}</div>`)) return;
    var b = el.querySelector('.px-retry');
    if (b) b.addEventListener('click', function () { fetchMatchDetails(false); });
  }

  // ------------------------------------------------------------------ main
  var matchId = new URLSearchParams(location.search).get('id') || '';
  var refreshTimer = null;
  var busy = false;
  var polling = false;        // true while the match is live / not started yet
  var nextDelay = REFRESH_MS; // interval chosen after the last fetch (never the remaining time)
  var lastFetch = 0;
  var failures = 0;           // consecutive failed refreshes -> exponential backoff
  var lastGood = { ev: null, lu: null };   // last valid events / lineup: a failed poll never blanks the UI
  var MAX_TIMER_MS = 6 * 60 * 60 * 1000;
  var MAX_BACKOFF_MS = 5 * 60 * 1000;
  var NO_KICKOFF_MS = 5 * 60 * 1000;                           // upcoming match without a usable timestamp

  // Arm the single timer. Any non-finite or tiny delay is clamped, so a bad value can never
  // turn into setTimeout(fn, NaN/0) and an immediate request loop.
  function arm(ms) {
    clearTimeout(refreshTimer);
    refreshTimer = null;
    if (!polling || document.hidden) return;                  // resumed by visibilitychange/pageshow
    ms = isFinite(ms) ? Math.min(Math.max(ms, 1000), MAX_TIMER_MS) : REFRESH_MS;
    refreshTimer = setTimeout(function () { fetchMatchDetails(true); }, ms);
  }
  function schedule(ms) {                                     // new interval after a fetch
    nextDelay = isFinite(ms) ? Math.min(Math.max(ms, 1000), MAX_TIMER_MS) : REFRESH_MS;
    arm(nextDelay);
  }
  function pause() { clearTimeout(refreshTimer); refreshTimer = null; }
  function resume() {
    if (!polling || document.hidden || busy) return;
    var due = lastFetch + nextDelay - Date.now();
    if (due <= 0) fetchMatchDetails(true); else arm(due);     // nextDelay stays the full interval
  }
  function kickoffMs(d) {                                     // 0 when missing / not a positive number
    var t = Number(d && d.match_timestamp);
    return isFinite(t) && t > 0 ? t * 1000 : 0;
  }
  // Decide the next refresh from the verified states only (0 = upcoming, 4 = finished, other
  // codes = live near kick-off, see statusOf). No undocumented status code is interpreted.
  function planNext(st, info) {
    if (st === 'live') { polling = true; schedule(REFRESH_MS); return; }
    if (st === 'upcoming') {
      var kick = kickoffMs(info), now = Date.now();
      if (!kick) { polling = true; schedule(NO_KICKOFF_MS); return; }   // slow, bounded
      if (now > kick + LIVE_WINDOW_MS) { polling = false; pause(); return; }   // still "not started" 3.5 h after kick-off: postponed / stale, stop
      var untilWindow = kick - 30 * 60 * 1000 - now;
      polling = true;
      schedule(untilWindow > PRE_MATCH_MS ? untilWindow : PRE_MATCH_MS);  // wake 30 min before kick-off
      return;
    }
    polling = false;                                         // finished / other: no more polling
    pause();
  }
  function heroShown() { return !!(heroParts && hero.contains(heroParts.center)); }
  // match_info must be an object with both teams; anything else (null body, wrapper without
  // data, array, error page parsed as JSON) is treated as a failed refresh.
  function isMatchInfo(d) {
    return !!d && typeof d === 'object' && !Array.isArray(d) &&
      !!d.home_team && typeof d.home_team === 'object' && !!d.away_team && typeof d.away_team === 'object';
  }
  document.addEventListener('visibilitychange', function () { if (document.hidden) pause(); else resume(); });
  window.addEventListener('pagehide', pause);                 // leaving / entering the back-forward cache
  window.addEventListener('pageshow', function (e) { if (e.persisted) resume(); });

  async function fetchMatchDetails(silent) {
    if (busy) return;
    pause();
    if (!/^\d{1,12}$/.test(matchId)) {
      message(hero, 'لم يتم تحديد المباراة. اختر مباراة من الصفحة الرئيسية.', false);
      setHtml(panels.events, ''); setHtml(panels.lineups, '');
      return;
    }
    // A retry while a score is on screen keeps the hero (last valid score) and reloads the panels only
    if (!silent) { if (!heroShown()) loader(hero, 'جاري تحميل المباراة...'); loader(panels.events); loader(panels.lineups); }
    if (!WORKER_BASE_URL || WORKER_BASE_URL.indexOf('<MY_WORKER_URL>') !== -1) {
      console.error('[PX League] Set PXL_WORKER_BASE_URL (top of the theme) to load match details.');
      return;                                                  // keep the spinners
    }
    busy = true;
    var ok = false, st = '', info = null;
    try {
      info = await fetchJson(api('match_info', matchId), silent ? 1 : 3);
      if (!isMatchInfo(info)) throw new Error('malformed match_info');
      applyStream(info.stream);                                // stream merged in by the Worker
      var results = await Promise.allSettled([
        Number(info.events) ? fetchJson(api('matches_event', matchId), silent ? 1 : 2).then(function (d) {
          if (!d || typeof d !== 'object' || !Array.isArray(d.events)) throw new Error('malformed matches_event');
          return d;
        }) : Promise.resolve(null),
        Number(info.lineup) ? fetchJson(api('matches_lineup', matchId), silent ? 1 : 2).then(function (d) {
          if (!d || typeof d !== 'object' || !d.lineup || typeof d.lineup !== 'object') throw new Error('malformed matches_lineup');
          return d;
        }) : Promise.resolve(null)
      ]);
      if (results[0].status === 'fulfilled') lastGood.ev = results[0].value;
      if (results[1].status === 'fulfilled') lastGood.lu = results[1].value;
      // A failed endpoint falls back to its last good copy, so shootout / halves / pitch stay on screen
      var n = normalize(info, lastGood.ev, lastGood.lu);

      st = renderHero(n);                                      // a throw here counts as a failed refresh
      // Panels: a failed or malformed response keeps what is on screen (silent) or offers a retry
      try {
        if (results[0].status === 'rejected' && !lastGood.ev) { if (!silent) message(panels.events, 'تعذّر تحميل الأحداث.', true); }
        else renderEvents(n);
      } catch (e) { console.warn('[PX League] render events:', e); }
      try {
        if (results[1].status === 'rejected' && !lastGood.lu) { if (!silent) message(panels.lineups, 'تعذّر تحميل التشكيلات.', true); }
        else renderLineups(n);
      } catch (e) { console.warn('[PX League] render lineups:', e); }
      ok = true;
    } catch (err) {
      console.warn('[PX League] match details:', err);
      if (!silent) {
        if (!heroShown()) {
          message(hero, String(err && err.message).indexOf('404') !== -1 ? 'المباراة غير موجودة.' : 'تعذّر تحميل بيانات المباراة.', true);
          setHtml(panels.events, ''); setHtml(panels.lineups, '');
        } else {                                               // keep the score, offer a retry in the panels
          message(panels.events, 'تعذّر تحميل الأحداث.', true);
          message(panels.lineups, 'تعذّر تحميل التشكيلات.', true);
        }
      }
    } finally {
      busy = false;
      lastFetch = Date.now();
      // Every outcome ends here, so neither a failed request, a malformed body, a render
      // exception nor a failed manual retry can leave a polling match without a timer.
      if (ok) {
        failures = 0;
        planNext(st, info);
      } else if (polling) {
        failures++;                                            // 60 s, 120 s, 240 s, then 5 min
        schedule(Math.min(PRE_MATCH_MS * Math.pow(2, failures), MAX_BACKOFF_MS));
      }
    }
  }

  // ------------------------------------------------------------------ tabs
  function selectTab(btn, focus) {
    tabs.forEach(function (t) {
      var on = t === btn;
      t.classList.toggle('is-active', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
      panels[t.getAttribute('data-tab')].hidden = !on;
    });
    if (focus) btn.focus();
    try { history.replaceState(null, '', location.pathname + location.search + '#' + btn.getAttribute('data-tab')); } catch (e) {}
  }
  page.querySelector('.match-tabs').addEventListener('click', function (e) {
    var b = e.target.closest('.match-tab');
    if (b) selectTab(b, false);
  });
  page.querySelector('.match-tabs').addEventListener('keydown', function (e) {
    if (e.key !== 'ArrowLeft' && e.key !== 'ArrowRight') return;
    var i = tabs.indexOf(document.activeElement);
    if (i === -1) return;
    e.preventDefault();
    var fwd = (e.key === 'ArrowLeft') === (document.documentElement.dir !== 'ltr');   // RTL: left = next, LTR: right = next
    selectTab(tabs[(i + (fwd ? 1 : -1) + tabs.length) % tabs.length], true);
  });
  var initialTab = tabs.filter(function (t) { return '#' + t.getAttribute('data-tab') === location.hash; })[0];
  if (initialTab) selectTab(initialTab, false);

  // ------------------------------------------------------------------ live stream (Match Controller)
  // The Worker merges the dashboard's match_settings into match_info:
  //   data.stream = { channel, r2_slug }   (absent = no stream)
  // match_info is refreshed every 30 s from 30 min before kick-off and while live, so a
  // stream attached or removed in the dashboard follows on the next refresh. No extra request.
  var STREAM_PLAYER_BASE = window.PXL_STREAM_PLAYER_BASE || 'https://live.smarterwho.site/player/';
  var STREAM_KEY_RE = /^[A-Za-z0-9_-]{1,64}$/;
  var streamBox = document.getElementById('match-stream');
  var streamSlot = document.getElementById('px-player-slot');
  var streamSrc = null;
  function streamUrl(s) {
    var channel = String(s.channel || ''), slug = String(s.r2_slug || '');
    var okChannel = STREAM_KEY_RE.test(channel), okSlug = STREAM_KEY_RE.test(slug);
    if (!okChannel && !okSlug) return '';
    var u = new URL(STREAM_PLAYER_BASE);
    if (okChannel) u.searchParams.set('channel', channel);
    if (okSlug) u.searchParams.set('r2', slug);
    return u.toString();
  }
  function showStream(src) {
    if (!streamBox || !streamSlot || src === streamSrc) return;   // same stream: never reload the player
    streamSrc = src;
    streamSlot.textContent = '';
    if (!src) { streamBox.hidden = true; return; }
    var f = document.createElement('iframe');
    f.src = src;
    f.title = 'البث المباشر';
    f.setAttribute('allow', 'autoplay; fullscreen; encrypted-media; picture-in-picture');
    f.setAttribute('allowfullscreen', 'true');
    streamSlot.appendChild(f);
    streamBox.hidden = false;
  }
  function applyStream(s) { showStream(s && typeof s === 'object' ? streamUrl(s) : ''); }

  // ------------------------------------------------------------------ self-test
  // Console: pxlSelfTest() (defaults to 5702737), or open /p/match.html?id=5702737&selftest=1
  window.pxlSelfTest = async function (id) {
    id = String(id || 5702737);
    var raw = await Promise.all([api('match_info', id), api('matches_event', id), api('matches_lineup', id)]
      .map(function (u) { return fetchJson(u, 2).catch(function () { return null; }); }));
    var n = normalize(raw[0], raw[1], raw[2]);
    console.log('[PX League] normalize(' + id + '):', n);
    if (id !== '5702737') return n;
    var goal = n.events.find(function (e) { return e.kind === 'goal'; });
    var subs = n.events.filter(function (e) { return e.kind === 'sub'; });
    var rows = function (s) { return (n.lineup[s]?.rows || []).map(function (r) { return r[0].row + r.length; }).join(' '); };
    console.table([
      ['score 1-0', n.score.home === 1 && n.score.away === 0],
      ['agg 1-1, Boca (away) qualified', n.agg?.home === 1 && n.agg?.away === 1 && n.agg?.winner === 'away'],
      ['shootout 3-4', n.penalties?.home.total === 3 && n.penalties?.away.total === 4],
      ['goal 72\x27 home', !!goal && goal.minute === 72 && goal.side === 'home'],
      ['subs at 57/63/78/78', subs.map(function (e) { return e.minute; }).sort().join('/') === '57/63/78/78'],
      ['sub OUT=player, IN=assist', subs.every(function (e) { return e.playerOut && e.playerIn; })],
      ['home 4-2-3-1 rows G1 D4 M2 F3 S1', n.home.formation === '4-2-3-1' && rows('home') === 'G1 D4 M2 F3 S1'],
      ['away 4-3-3 rows G1 D4 M3 F3', n.away.formation === '4-3-3' && rows('away') === 'G1 D4 M3 F3']
    ].map(function (c) { return { check: c[0], ok: c[1] }; }));
    return n;
  };
  if (new URLSearchParams(location.search).get('selftest') === '1') window.pxlSelfTest(matchId);

  window.fetchMatchDetails = fetchMatchDetails;
  fetchMatchDetails(false);
})();
//

//
(function () {
  var slot = document.getElementById('px-player-slot');
  var body = document.getElementById('px-post-body');
  if (!slot || !body) return;

  var frame = null;
  var marker = body.querySelector('[data-stream-src]');
  if (marker) {
    var src = marker.getAttribute('data-stream-src') || '';
    if (/^https:\/\//i.test(src)) {
      frame = document.createElement('iframe');
      frame.src = src;
    }
    marker.remove();
  } else {
    frame = body.querySelector('iframe');
  }
  if (!frame) return;   // regular article: the arena stays hidden, the post shows normally

  frame.setAttribute('allow', 'autoplay; fullscreen; encrypted-media; picture-in-picture');
  frame.setAttribute('allowfullscreen', 'true');
  frame.setAttribute('title', document.title);
  frame.removeAttribute('width');
  frame.removeAttribute('height');
  frame.removeAttribute('style');
  slot.textContent = '';
  slot.appendChild(frame);

  // Stream found: show the arena (its title replaces the article title)
  var arena = document.getElementById('px-arena');
  var postTitle = document.getElementById('px-post-title');
  if (arena) arena.hidden = false;
  if (postTitle) postTitle.hidden = true;
  if (!arena) return;

  // Ads: only slots with real ad code, and only after the player iframe has loaded
  // (never beside an empty player or a loading placeholder). adsbygoogle is pushed
  // here, once the slot is visible: a push into a hidden slot fails for good
  // ("availableWidth=0"), which is why the widgets must not push themselves.
  var slots = arena.querySelectorAll('.ad-slot');
  for (var i = 0; i < slots.length; i++) {
    if (slots[i].querySelector('ins.adsbygoogle, iframe, img')) slots[i].classList.add('is-filled');
  }
  var shown = false;
  function showAds() {
    if (shown) return;
    shown = true;
    arena.classList.add('is-ready');
    var ins = arena.querySelectorAll('.ad-slot.is-filled ins.adsbygoogle:not([data-adsbygoogle-status])');
    for (var j = 0; j < ins.length; j++) {
      try { (window.adsbygoogle = window.adsbygoogle || []).push({}); } catch (e) {}
    }
  }
  frame.addEventListener('load', showAds, { once: true });
})();
